using System.Text.Json;
using W=System.Windows;
using M=System.Windows.Media;
using I=System.Windows.Media.Imaging;
namespace CombinedStudio;
// Render the creator's resting layers. Crosshair X firing scripts and GIF timelines are not executed.
internal sealed class CrosshairCommunityDrawing {
 static readonly Dictionary<string,(long Stamp,CrosshairCommunityDrawing Drawing)> prepared=new();
 internal static CrosshairCommunityDrawing Load(string path){long stamp=File.GetLastWriteTimeUtc(path).Ticks;if(prepared.TryGetValue(path,out var cached)&&cached.Stamp==stamp)return cached.Drawing;var drawing=new CrosshairCommunityDrawing(path);if(prepared.Count>=32)prepared.Remove(prepared.Keys.First());prepared[path]=(stamp,drawing);return drawing;}
 internal void RequireVisibleOverlay(){var visual=new M.DrawingVisual();using(var dc=visual.RenderOpen()){dc.PushTransform(new M.TranslateTransform(160,160));Draw(dc);}var bitmap=new I.RenderTargetBitmap(320,320,96,96,M.PixelFormats.Pbgra32);bitmap.Render(visual);var pixels=new byte[320*320*4];bitmap.CopyPixels(pixels,320*4,0);if(!Enumerable.Range(0,320*320).Any(i=>pixels[i*4+3]>0))throw new ArgumentException("This upload has no visible resting crosshair in the overlay area.");}
 readonly M.DrawingGroup drawing;readonly JsonElement source;M.DrawingGroup adjusted;int? adjustedThickness,adjustedGap;
 internal CrosshairCommunityDrawing(string path){using var doc=JsonDocument.Parse(File.ReadAllText(path));Validate(doc.RootElement);source=doc.RootElement.Clone();drawing=new();using(var dc=drawing.Open())foreach(var layer in doc.RootElement.GetProperty("model").EnumerateArray())DrawLayer(dc,layer);drawing.Freeze();}
 internal void Draw(M.DrawingContext dc,int? lineThickness=null,int? centerGap=null){if(lineThickness==null&&centerGap==null){dc.DrawDrawing(drawing);return;}if(adjusted==null||adjustedThickness!=lineThickness||adjustedGap!=centerGap){var updated=new M.DrawingGroup();using(var content=updated.Open())foreach(var layer in source.GetProperty("model").EnumerateArray())DrawLayer(content,layer,lineThickness,centerGap);updated.Freeze();adjusted=updated;adjustedThickness=lineThickness;adjustedGap=centerGap;}dc.DrawDrawing(adjusted);}
 internal static JsonElement Property(JsonElement obj,string key)=>obj.ValueKind==JsonValueKind.Object&&obj.TryGetProperty(key,out var value)?value:default;
 static double Number(JsonElement obj,string key,double fallback=0){var value=Property(obj,key);double result=value.ValueKind==JsonValueKind.Number?value.GetDouble():fallback;if(!double.IsFinite(result)||Math.Abs(result)>10000)throw new ArgumentException("Crosshair layer contains an invalid number.");return result;}
 static string Text(JsonElement obj,string key,string fallback="")=>Property(obj,key).ValueKind==JsonValueKind.String?Property(obj,key).GetString()!:fallback;
 internal static void Validate(JsonElement root){var layers=Property(root,"model");if(layers.ValueKind!=JsonValueKind.Array||layers.GetArrayLength()==0||layers.GetArrayLength()>64)throw new ArgumentException("Unsupported crosshair layer count.");foreach(var layer in layers.EnumerateArray()){string type=Text(layer,"type","model");if(type!="image"&&type!="model")throw new ArgumentException("Unsupported community layer: "+type+". Open its source page for the original.");}}
 static M.SolidColorBrush Brush(JsonElement obj,string fallback="#FFFFFF"){var color=(M.Color)M.ColorConverter.ConvertFromString(Text(obj,"color",fallback));color.A=(byte)Math.Round(Math.Clamp(Number(obj,"opacity",1),0,1)*255);return new(color);}
 static void DrawLayer(M.DrawingContext dc,JsonElement layer,int? lineThickness=null,int? centerGap=null){var position=Property(layer,"position");double scale=Math.Clamp(Number(Property(layer,"layer"),"size",1),.001,10);dc.PushTransform(new M.TranslateTransform(Number(position,"x"),Number(position,"y")));dc.PushTransform(new M.ScaleTransform(scale,scale));dc.PushTransform(new M.RotateTransform(Number(layer,"rotation")));
  if(Text(layer,"type")=="image"){
   string encoded=Text(layer,"image");int comma=encoded.IndexOf(',');if(comma>=0)encoded=encoded.Substring(comma+1);if(encoded.Length>24*1024*1024)throw new ArgumentException("Image layer is too large.");byte[] bytes=Convert.FromBase64String(encoded);using var stream=new MemoryStream(bytes);var image=I.BitmapDecoder.Create(stream,I.BitmapCreateOptions.PreservePixelFormat,I.BitmapCacheOption.OnLoad).Frames[0];if(image.PixelWidth>4096||image.PixelHeight>4096)throw new ArgumentException("Image layer dimensions exceed 4096 pixels.");image.Freeze();double width=Math.Clamp(Number(layer,"width",image.PixelWidth),1,4096),height=Math.Clamp(Number(layer,"height",image.PixelHeight),1,4096);dc.PushOpacity(Math.Clamp(Number(layer,"opacity",1),0,1));dc.DrawImage(image,new W.Rect(-width/2,-height/2,width,height));dc.Pop();
  }else{
   var outline=Property(layer,"outline");double thickness=Math.Clamp(Number(outline,"thickness"),0,100);var outlineBrush=Brush(outline,"#000000");
   void Shape(M.Geometry geometry,JsonElement component,bool ring=false){var group=new M.DrawingGroup();using(var content=group.Open()){double ringWidth=Math.Max(1,Number(component,"thickness",1));if(thickness>0)content.DrawGeometry(ring?null:outlineBrush,new M.Pen(outlineBrush,(ring?ringWidth:0)+thickness*2),geometry);content.DrawGeometry(ring?null:Brush(component),ring?new M.Pen(Brush(component),ringWidth):null,geometry);}double blur=Math.Clamp(Number(component,"blur"),0,50);if(blur>0){var visual=new M.DrawingVisual{Effect=new System.Windows.Media.Effects.BlurEffect{Radius=blur}};using(var ctx=visual.RenderOpen())ctx.DrawDrawing(group);var bounds=group.Bounds;bounds.Inflate(blur*2,blur*2);if(!bounds.IsEmpty&&bounds.Width<=4096&&bounds.Height<=4096){var bitmap=new I.RenderTargetBitmap(Math.Max(1,(int)Math.Ceiling(bounds.Width)),Math.Max(1,(int)Math.Ceiling(bounds.Height)),96,96,M.PixelFormats.Pbgra32);var translated=new M.DrawingVisual();using(var ctx=translated.RenderOpen()){ctx.PushTransform(new M.TranslateTransform(-bounds.X,-bounds.Y));ctx.DrawDrawing(group);}translated.Effect=visual.Effect;bitmap.Render(translated);bitmap.Freeze();dc.DrawImage(bitmap,bounds);}else dc.DrawDrawing(group);}else dc.DrawDrawing(group);}
   var dot=Property(layer,"dot");double diameter=Math.Clamp(Number(dot,"diameter"),0,1000);if(diameter>0&&Number(dot,"opacity",1)>0){string shape=Text(dot,"shape","circle");double r=diameter/2;M.Geometry geometry=shape switch{"circle" or "ring"=>new M.EllipseGeometry(new W.Point(),r,r),"square"=>new M.RectangleGeometry(new W.Rect(-r,-r,diameter,diameter)),"diamond"=>Polygon(new[]{new W.Point(0,-r),new W.Point(r,0),new W.Point(0,r),new W.Point(-r,0)}),_=>throw new ArgumentException("Unsupported dot shape: "+shape)};Shape(geometry,dot,shape=="ring");}
   var line=Property(layer,"line");double length=Math.Clamp(Number(line,"length"),0,1000),width=Math.Clamp(Number(line,"thickness"),0,1000),gap=Math.Clamp(Number(line,"offset"),-1000,1000);if(width>0&&lineThickness.HasValue)width=lineThickness.Value;if(centerGap.HasValue)gap=centerGap.Value;dc.PushTransform(new M.RotateTransform(Number(line,"rotation")));if(length>0&&width>0&&Number(line,"opacity",1)>0){var visible=Property(line,"visible");string[] directions=visible.ValueKind==JsonValueKind.Array?visible.EnumerateArray().Select(x=>x.GetString()??"").ToArray():new[]{"top","left","right","bottom"};foreach(string direction in directions){double rotation=direction switch{"right"=>0,"bottom"=>90,"left"=>180,"top"=>270,_=>throw new ArgumentException("Unsupported line direction: "+direction)};dc.PushTransform(new M.RotateTransform(rotation));string shape=Text(line,"shape","rectangle");M.Geometry geometry=shape switch{"rectangle"=>new M.RectangleGeometry(new W.Rect(gap,-width/2,length,width)),"triangle"=>Polygon(new[]{new W.Point(gap,0),new W.Point(gap+length,-width/2),new W.Point(gap+length,width/2)}),"circle"=>new M.EllipseGeometry(new W.Rect(gap,-width/2,length,width)),_=>throw new ArgumentException("Unsupported line shape: "+shape)};Shape(geometry,line);dc.Pop();}}dc.Pop();
  }dc.Pop();dc.Pop();dc.Pop();
 }
 static M.Geometry Polygon(W.Point[] points){var geometry=new M.StreamGeometry();using(var context=geometry.Open()){context.BeginFigure(points[0],true,true);context.PolyLineTo(points.Skip(1).ToArray(),true,false);}return geometry;}
}
